<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import type { ModalidadPago, ModalidadPagoPayload } from '../interfaces/modalidad-pago.interface'
import { desactivarModalidadPago, guardarModalidadPago, listarModalidadesPago, obtenerModalidadPago } from '../services/modalidad-pago'
const rows = ref<ModalidadPago[]>([]), search = ref(''), page = ref(1), lastPage = ref(1), total = ref(0), loading = ref(false), error = ref(''), success = ref(''), showForm = ref(false), editing = ref<number | null>(null)
const form = reactive<ModalidadPagoPayload>({ detalle: '', activo: true })
const message = (e: unknown) => e instanceof Error ? e.message : 'No se pudo completar la operación.'
async function load(next = 1) { loading.value = true; error.value = ''; try { const r = await listarModalidadesPago(search.value, next); rows.value = r.data; page.value = r.current_page; lastPage.value = r.last_page; total.value = r.total } catch (e) { error.value = message(e) } finally { loading.value = false } }
function create() { editing.value = null; Object.assign(form, { detalle: '', activo: true }); showForm.value = true }
async function edit(item: ModalidadPago) { loading.value = true; try { const x = await obtenerModalidadPago(item.id); editing.value = x.id; Object.assign(form, { detalle: x.detalle, activo: Boolean(x.activo) }); showForm.value = true } catch (e) { error.value = message(e) } finally { loading.value = false } }
async function save() { loading.value = true; error.value = ''; try { await guardarModalidadPago(editing.value, { ...form }); success.value = `Modalidad de pago ${editing.value ? 'actualizada' : 'registrada'} correctamente.`; showForm.value = false; await load(page.value) } catch (e) { error.value = message(e) } finally { loading.value = false } }
async function deactivate(item: ModalidadPago) { if (!confirm(`¿Desactivar la modalidad ${item.detalle}?`)) return; loading.value = true; try { await desactivarModalidadPago(item.id); success.value = 'Modalidad de pago desactivada correctamente.'; await load(page.value) } catch (e) { error.value = message(e) } finally { loading.value = false } }
function clear() { search.value = ''; load(1) }
onMounted(() => load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Finanzas / Modalidades de pago</nav><header class="hero"><div class="mark">MP</div><div><small>MIA · FINANZAS · MAESTROS</small><h1>Modalidades de pago</h1><p>Catálogo de formas utilizadas para efectuar operaciones y pagos financieros.</p></div><strong>{{total}} registros</strong><button @click="create">+ Nueva modalidad</button></header><p v-if="error" class="flash badmsg">{{error}}</p><p v-if="success" class="flash okmsg">{{success}}</p><form class="filters" @submit.prevent="load(1)"><input v-model.trim="search" placeholder="Buscar por identificador o detalle"><button>Buscar</button><button type="button" class="soft" @click="clear">Limpiar</button></form><section class="card"><div v-if="loading" class="empty">Procesando…</div><div v-else-if="!rows.length" class="empty">No se encontraron modalidades de pago.</div><div v-else class="grid"><article v-for="item in rows" :key="item.id" :class="{inactive:!item.activo}"><header><b>#{{item.id}}</b><span :class="item.activo?'good':'bad'">{{item.activo?'ACTIVA':'INACTIVA'}}</span></header><h2>{{item.detalle}}</h2><footer><button class="edit" @click="edit(item)">Editar</button><button v-if="item.activo" class="danger" @click="deactivate(item)">Desactivar</button></footer></article></div><footer v-if="lastPage>1" class="pager"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>{{page}} / {{lastPage}}</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer></section><div v-if="showForm" class="backdrop" @mousedown.self="showForm=false"><form class="dialog" @submit.prevent="save"><header><div><small>{{editing?'EDICIÓN':'NUEVO REGISTRO'}}</small><h2>{{editing?'Editar':'Registrar'}} modalidad de pago</h2></div><button type="button" @click="showForm=false">×</button></header><label>Detalle<input v-model.trim="form.detalle" maxlength="150" required placeholder="Nombre de la modalidad"></label><label class="check"><input v-model="form.activo" type="checkbox"> Modalidad activa</label><footer><button type="button" class="soft" @click="showForm=false">Cancelar</button><button :disabled="loading">Guardar</button></footer></form></div></div></template>
<style scoped>
