}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#172b3d88}.dialog{width:min(500px,100%);padding:20px;box-sizing:border-box;border-radius:12px;background:#fff}.dialog>header{display:flex}.dialog>header div{flex:1}.dialog h2{margin:3px 0 15px}.dialog>header button{color:#66757b;background:none;font-size:1.2rem}.dialog label{display:grid;gap:5px;margin:10px 0;font-size:.52rem;font-weight:700}.dialog .check{display:flex;align-items:center}.dialog .check input{width:auto}.dialog footer{display:flex;justify-content:center;gap:8px;margin-top:15px}@media(max-width:950px){.grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){.filters,.grid{grid-template-columns:1fr}.hero{flex-wrap:wrap}.mark{display:none}}
</style>
